import pyomo.environ as pyo

DATA = {
    "foods": ["Chicken", "Broccoli", "Beef", "Rice"],
    "nutrients": ["protein", "carb", "calories"],
    # cost per unit of each food
    "cost": {
        "Chicken": 5,
        "Broccoli": 5,
        "Beef": 8,
        "Rice": 3,
    },
    # nutrient content per unit of each food
    "content": {
        "protein":  {"Chicken": 10, "Broccoli": 4,  "Beef": 13, "Rice": 15},
        "carb":     {"Chicken": 17, "Broccoli": 3,  "Beef": 8,  "Rice": 25},
        "calories": {"Chicken": 159, "Broccoli": 126, "Beef": 230, "Rice": 112},
    },
    # minimum required intake per nutrient
    "requirement": {
        "protein": 66,
        "carb": 101,
        "calories": 1701,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.F = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    # Decision: servings of each food (continuous, nonnegative)
    model.x = pyo.Var(model.F, within=pyo.NonNegativeReals)

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.F)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each nutrient must meet its minimum requirement (>=)
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.x[i] for i in m.F) >= d["requirement"][n]
    model.nutrient = pyo.Constraint(model.N, rule=nutrient_rule)

    return model

